import { RangeMan } from '@boss/h-table';
import { describe, test, expect } from 'vitest';

const Range = [10, 10, 20, 20];
describe('测试 rangeMan', () => {
  // describe('[4,1,4,2]', () => {
  //   test('[4,1,4,2]', () => {
  //     const new1 = RangeMan.applyRemoveCol([4, 1, 4, 2], { at: 4, count: 2 });
  //     expect(new1).toBeUndefined();
  //   });
  // });
  describe('插入、删除行', () => {
    test('在 Range 前插入行', () => {
      const new1 = RangeMan.applyInsertRow(Range, { at: 9, count: 1 });
      expect(new1).toEqual([10, 10 + 1, 20, 20 + 1]);
      const new2 = RangeMan.applyInsertRow(Range, { at: 10, count: 2 });
      expect(new2).toEqual([10, 10 + 2, 20, 20 + 2]);
    });
    test('在 Range 中插入行', () => {
      const new1 = RangeMan.applyInsertRow(Range, { at: 11, count: 1 });
      expect(new1).toEqual([10, 10, 20, 20 + 1]);
      const new2 = RangeMan.applyInsertRow(Range, { at: 20, count: 2 });
      expect(new2).toEqual([10, 10, 20, 20 + 2]);
    });

    test('在 Range 后插入行', () => {
      const new1 = RangeMan.applyInsertRow(Range, { at: 21, count: 1 });
      expect(new1).toEqual([10, 10, 20, 20]);
    });

    test('在 Range 前删除行', () => {
      const new1 = RangeMan.applyRemoveRow(Range, { at: 9, count: 1 });
      expect(new1).toEqual([10, 10 - 1, 20, 20 - 1]);
    });

    test('在 Range 中删除行', () => {
      const new1 = RangeMan.applyRemoveRow(Range, { at: 10, count: 2 });
      expect(new1).toEqual([10, 10, 20, 20 - 2]);
      const new2 = RangeMan.applyRemoveRow(Range, { at: 19, count: 1 });
      expect(new2).toEqual([10, 10, 20, 20 - 1]);
      const new3 = RangeMan.applyRemoveRow(Range, { at: 20, count: 1 });
      expect(new3).toEqual([10, 10, 20, 20 - 1]);
    });

    test('在 Range 后删除行相交', () => {
      const new1 = RangeMan.applyRemoveRow(Range, { at: 21, count: 20 });
      expect(new1).toEqual([10, 10, 20, 20]);
    });

    test('在 Range 删除行相交', () => {
      const new1 = RangeMan.applyRemoveRow(Range, { at: 15, count: 20 });
      expect(new1).toEqual([10, 10, 20, 14]);
    });
    test('在 Range 删除行包含', () => {
      const new1 = RangeMan.applyRemoveRow(Range, { at: 9, count: 20 });
      expect(new1).toBeUndefined();
      const new2 = RangeMan.applyRemoveRow(Range, { at: 10, count: 20 });
      expect(new2).toBeUndefined();
    });
  });

  describe('插入、删除列', () => {
    test('在 Range 前插入列', () => {
      const new1 = RangeMan.applyInsertCol(Range, { at: 9, count: 1 });
      expect(new1).toEqual([10 + 1, 10, 20 + 1, 20]);
      const new2 = RangeMan.applyInsertCol(Range, { at: 10, count: 2 });
      expect(new2).toEqual([10 + 2, 10, 20 + 2, 20]);
    });
    test('在 Range 中插入列', () => {
      const new1 = RangeMan.applyInsertCol(Range, { at: 11, count: 1 });
      expect(new1).toEqual([10, 10, 20 + 1, 20]);
      const new2 = RangeMan.applyInsertCol(Range, { at: 20, count: 2 });
      expect(new2).toEqual([10, 10, 20 + 2, 20]);
    });

    test('在 Range 后插入列', () => {
      const new1 = RangeMan.applyInsertCol(Range, { at: 21, count: 1 });
      expect(new1).toEqual([10, 10, 20, 20]);
    });

    test('在 Range 前删除列', () => {
      const new1 = RangeMan.applyRemoveCol(Range, { at: 9, count: 1 });
      expect(new1).toEqual([10 - 1, 10, 20 - 1, 20]);
    });

    test('在 Range 中删除列', () => {
      const new1 = RangeMan.applyRemoveCol(Range, { at: 10, count: 2 });
      expect(new1).toEqual([10, 10, 20 - 2, 20]);
      const new2 = RangeMan.applyRemoveCol(Range, { at: 19, count: 1 });
      expect(new2).toEqual([10, 10, 20 - 1, 20]);
      const new3 = RangeMan.applyRemoveCol(Range, { at: 20, count: 1 });
      expect(new3).toEqual([10, 10, 20 - 1, 20]);
    });

    test('在 Range 后删除列相交', () => {
      const new1 = RangeMan.applyRemoveCol(Range, { at: 21, count: 20 });
      expect(new1).toEqual([10, 10, 20, 20]);
    });

    test('在 Range 删除列相交', () => {
      const new1 = RangeMan.applyRemoveCol(Range, { at: 15, count: 20 });
      expect(new1).toEqual([10, 10, 15 - 1, 20]);
    });
    test('在 Range 删除列包含', () => {
      const new1 = RangeMan.applyRemoveCol(Range, { at: 9, count: 20 });
      expect(new1).toBeUndefined();
      const new2 = RangeMan.applyRemoveCol(Range, { at: 10, count: 20 });
      expect(new2).toBeUndefined();
    });
  });
});
